                 //       "pairSymbolNormalized": "BTC_USDT",
                 //       "type": "buy",
                 //       "method": "limit",
                 //       "orderClientId":
                 //       "2ed187bd-59a8-4875-a212-1b793963b85c", "time":
                 //       "1618913189253", "updateTime": "1618913189253",
                 //       "status": "Untouched",
                 //       "leftAmount": "0.0003000000000000"
