  virtual std::any parseOrderStatus(std::any status) {
    std::any statuses = ccxt::dict{
        {std::string("Untouched"), std::string("open")},
        {std::string("Partial"), std::string("open")},
        {std::string("Canceled"), std::string("canceled")},
        {std::string("Closed"), std::string("closed")},
    };
    return this->safeString(statuses, status, status);
  }

  std::any parseOrder(std::any order, std::any market = std::any{}) override {
    //
    // fetchOrders / fetchOpenOrders
    //     {
    //       "id": 2605984008,
    //       "price": "55000",
    //       "amount": "0.00050000",
    //       "quantity": "0.00050000",
    //       "stopPrice": "0",
    //       "pairSymbol": "BTCUSDT",
    //       "pairSymbolNormalized": "BTC_USDT",
    //       "type": "buy",
    //       "method": "limit",
    //       "orderClientId": "f479bdb6-0965-4f03-95b5-daeb7aa5a3a5",
    //       "time": 0,
    //       "updateTime": 1618913083543,
    //       "status": "Untouched",
    //       "leftAmount": "0.00050000"
    //     }
    //
    // createOrder
    //     {
    //       "id": "2606935102",
    //       "quantity": "0.0002",
    //       "price": "56000",
    //       "stopPrice": null,
    //       "newOrderClientId": "98e5c491-7ed9-462b-9666-93553180fb28",
    //       "type": "buy",
    //       "method": "limit",
    //       "pairSymbol": "BTCUSDT",
    //       "pairSymbolNormalized": "BTC_USDT",
    //       "datetime": "1618916479523"
    //     }
    //
    std::any id = this->safeString(order, std::string("id"));
    std::any price = this->safeString(order, std::string("price"));
    std::any amountString = this->safeString2(order, std::string("amount"),
                                              std::string("quantity"));
    std::any amount = ccxt::Precise::stringAbs(amountString);
    std::any remaining = this->safeString(order, std::string("leftAmount"));
    std::any marketId = this->safeString(order, std::string("pairSymbol"));
    std::any symbol = this->safeSymbol(marketId, market);
    std::any side = this->safeString(order, std::string("type"));
    std::any type = this->safeString(order, std::string("method"));
    std::any clientOrderId =
        this->safeString(order, std::string("orderClientId"));
    std::any timestamp = this->safeInteger2(order, std::string("updateTime"),
                                            std::string("datetime"));
    std::any rawStatus = this->safeString(order, std::string("status"));
    std::any status = this->parseOrderStatus(rawStatus);
    return this->safeOrder(
        ccxt::dict{
            {std::string("info"), order},
            {std::string("id"), id},
            {std::string("price"), price},
            {std::string("amount"), amount},
            {std::string("remaining"), remaining},
            {std::string("filled"), std::any{}},
            {std::string("cost"), std::any{}},
            {std::string("average"), std::any{}},
            {std::string("status"), status},
            {std::string("side"), side},
            {std::string("type"), type},
            {std::string("clientOrderId"), clientOrderId},
            {std::string("timestamp"), timestamp},
            {std::string("datetime"), this->iso8601(timestamp)},
            {std::string("symbol"), symbol},
            {std::string("fee"), std::any{}},
        },
        market);
  }

  /**
   * @method
   * @name btcturk#fetchMyTrades
   * @description fetch all trades made by the user
   * @see https://docs.btcturk.com/private-endpoints/user-transactions
   * @param {string} symbol unified market symbol
   * @param {int} [since] the earliest time in ms to fetch trades for
   * @param {int} [limit] the maximum number of trades structures to retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {Trade[]} a list of [trade structures]{@link
   * https://docs.ccxt.com/?id=trade-structure}
   */
  std::shared_future<std::any>
  fetchMyTrades(std::any symbol = std::any{}, std::any since = std::any{},
                std::any limit = std::any{},
                std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any market = std::any{};
                 if (isTrue(!isEqual(symbol, std::any{}))) {
                   market = this->market(symbol);
                 }
                 std::any response =
                     awaitValue(this->privateGetUsersTransactionsTrade());
                 //
                 //     {
                 //       "data": [
                 //         {
                 //           "price": "56000",
                 //           "numeratorSymbol": "BTC",
                 //           "denominatorSymbol": "USDT",
                 //           "orderType": "buy",
                 //           "orderId": "2606935102",
                 //           "id": "320874372",
                 //           "timestamp": "1618916479593",
                 //           "amount": "0.00020000",
                 //           "fee": "0",
                 //           "tax": "0"
                 //         }
                 //       ],
                 //       "success": true,
                 //       "message": "SUCCESS",
                 //       "code": "0"
                 //     }
                 //
                 std::any data = this->safeList(response, std::string("data"));
                 std::any dataList = ccxt::list{};
                 if (isTrue(!isEqual(data, std::any{}))) {
                   dataList = data;
                 }
                 return this->parseTrades(dataList, market, since, limit);
               })
        .share();
  }

  std::any nonce() override { return this->milliseconds(); }

  std::any sign(std::any path, std::any api = std::string("public"),
                std::any method = std::string("GET"),
                std::any params = ccxt::dict{}, std::any headers = std::any{},
                std::any body = std::any{}) override {
    if (isTrue(isEqual(this->id, std::string("btctrader")))) {
      throw ExchangeError(toString(add(
          this->id,
          std::string(" is an abstract base API for BTCExchange, BTCTurk"))));
    }
    std::any url =
        add(add(::getValue(::getValue(this->urls, std::string("api")), api),
                std::string("/")),
            path);
    if (isTrue(isTrue((isEqual(method, std::string("GET")))) ||
               isTrue((isEqual(method, std::string("DELETE")))))) {
      if (isTrue(isGreaterThan(getArrayLength(getObjectKeys(params)), 0))) {
        url = add(url, add(std::string("?"), this->urlencode(params)));
      }
    } else {
      body = this->json(params);
    }
    if (isTrue(isEqual(api, std::string("private")))) {
      this->checkRequiredCredentials();
      std::any nonce = toString(this->nonce());
      std::any secret = this->base64ToBinary(this->secret);
      std::any auth = add(this->apiKey, nonce);
      headers = ccxt::dict{
          {std::string("X-PCK"), this->apiKey},
          {std::string("X-Stamp"), nonce},
          {std::string("X-Signature"),
           this->hmac(this->encode(auth), secret, sha256,
                      std::string("base64"))},
          {std::string("Content-Type"), std::string("application/json")},
      };
    }
    return ccxt::dict{
        {std::string("url"), url},
        {std::string("method"), method},
        {std::string("body"), body},
        {std::string("headers"), headers},
    };
  }

  std::any handleErrors(std::any code, std::any reason, std::any url,
                        std::any method, std::any headers, std::any body,
                        std::any response, std::any requestHeaders,
                        std::any requestBody) override {
    std::any errorCode =
        this->safeString(response, std::string("code"), std::string("0"));
    std::any message = this->safeString(response, std::string("message"));
    std::any output =
        (isTrue((isEqual(message, std::any{}))) ? std::any(body)
                                                : std::any(message));
    this->throwExactlyMatchedException(
        ::getValue(this->exceptions, std::string("exact")), message,
        add(add(this->id, std::string(" ")), output));
    if (isTrue(isTrue((!isEqual(errorCode, std::string("0")))) &&
               isTrue((!isEqual(errorCode, std::string("SUCCESS")))))) {
      throw ExchangeError(
          toString(add(add(this->id, std::string(" ")), output)));
    }
    return std::any{};
  }
